const version = '1.20.4', data = minecraftData(version);
const stone = data.blocksByName.stone.defaultState;
const slab = data.blocksByName.stone_slab.defaultState;
const water = data.blocksByName.water.defaultState;
const enc = new TextEncoder();
const join = arrays => Buffer.concat(arrays.map(array => Buffer.from(array)));
function varint(value) { const out = []; do { const byte = value & 127; value >>>= 7; out.push(byte | (value ? 128 : 0)); } while (value); return Buffer.from(out); }
function crc(bytes) { let value = 0xffffffff; for (const byte of bytes) { value ^= byte; for (let bit = 0; bit < 8; bit++) value = (value >>> 1) ^ ((value & 1) ? 0xedb88320 : 0); } return (value ^ 0xffffffff) >>> 0; }
