  if (type === 8) return nbtString(value);
  if (type === 7) return join([nbtInteger(4, value.length), value]);
  if (type === 10) return join([...Object.entries(value).map(([name, [childType, child]]) => join([[childType], nbtString(name), nbtPayload(childType, child)])), [0]]);
