  page.on('console', message => { if (message.type() === 'error' && !message.text().includes('favicon.ico')) browserErrors.push(message.text()); });
  await page.goto(url);
  await page.waitForFunction(() => document.documentElement.dataset.engine === 'ready' || document.documentElement.dataset.engine === 'error', null, { timeout: 60000 });
  assert.equal(await page.locator('html').getAttribute('data-engine'), 'ready', await page.locator('#error').textContent());
  await page.evaluate(() => { document.querySelector('#adaptive').checked = false; document.querySelector('#cycle').checked = false; });
  await page.locator('#resource-pack').setInputFiles({ name: 'pomme-test-resources.zip', mimeType: 'application/zip', buffer: resourcePack() });
  await page.waitForFunction(() => document.querySelector('#pack-status').textContent.includes('block states') && document.documentElement.dataset.engine !== 'error', null, { timeout: 30000 });
  assert.equal(await page.evaluate(() => window.pomme.renderer.stats().atlasTileCount), 2);
  console.log('Original fixture pack imported; joining Java server through the TCP gateway.');
  await page.evaluate(async options => { await window.pomme.connectServer(options); }, { host: '127.0.0.1', port, username: 'PommeBrowser', auth: 'offline', gateway: `ws://127.0.0.1:${gateway.address.port}` });
  await page.waitForFunction(state => window.pomme.session?.state.status === 'playing' && window.pomme.core.block_get(-9, -20, -10) === state, slab, { timeout: 30000 });
  await page.waitForFunction(() => window.pomme.world.keys.has('-1,-1') && window.pomme.renderer.stats().dynamicMeshes > 0 && window.pomme.renderer.stats().historyUsed, null, { timeout: 30000 });
  const proof = await page.evaluate(() => ({
    mode: window.pomme.mode, dimension: [window.pomme.core.world_min_y(), window.pomme.core.world_height()],
    position: [...window.pomme.player.position], health: window.pomme.session.state.health,
    food: window.pomme.session.state.food, count: window.pomme.session.windows.get(0).slots[36].itemCount,
    solidSlab: window.pomme.core.collides_aabb(-8.9,-19.9,-9.9,-8.1,-19.6,-9.1),
    emptySlabTop: window.pomme.core.collides_aabb(-8.9,-19.4,-9.9,-8.1,-18,-9.1),
    lightSections: window.pomme.core.world_light_section_count(),
    renderer: window.pomme.renderer.stats(),
  }));
