  assert.ok(proof.position[0] < 0 && proof.position[1] < 0 && proof.position[2] < 0);
  assert.equal(proof.solidSlab, 1); assert.equal(proof.emptySlabTop, 0);
  assert.equal(proof.health, 16); assert.equal(proof.food, 18); assert.equal(proof.count, 32);
  assert.ok(proof.lightSections > 0, 'server light data reaches the actual WASM world');
  assert.match(await page.getByRole('log', { name: 'Server chat' }).textContent(), /Browser integration ready/);
  assert.equal(proof.renderer.temporalEnabled, true); assert.equal(proof.renderer.ssrEnabled, true);
  assert.equal(proof.renderer.dynamicMeshes, 1); assert.ok(proof.renderer.entityTriangles > 0);
  assert.equal((await received.wait('teleport_confirm')).params.teleportId, 7);
  await received.wait('keep_alive'); await received.wait('chunk_batch_received');

  // Server correction remains authoritative and the client sends actual native
  // coordinates back on its own 20 Hz network tick.
  const checkpoint = received.packets.length;
  joined.write('position', { x: -7.5, y: -20, z: -8.5, yaw: 180, pitch: 12, flags: 0, teleportId: 8 });
  await received.wait('teleport_confirm', params => params.teleportId === 8, checkpoint);
  await page.waitForFunction(() => Math.abs(window.pomme.player.position[0] + 7.5) < 0.001);
  const movement = await received.wait('position_look', params => Math.abs(params.x + 7.5) < 0.001, checkpoint);
