  assert.equal((await page.evaluate(() => window.pomme.player.target()))[6], slab, 'visible slab can be picked using its exact model');
  await page.mouse.down({ button: 'left' });
  await page.mouse.up({ button: 'left' });
  const dig = await received.wait('block_dig', params => params.location.x === -9 && params.location.y === -20);
  assert.equal(dig.params.status, 0);
  assert.equal(await page.evaluate(() => window.pomme.core.block_get(-9,-20,-10)), slab, 'digging waits for the server response');
  const beforeUpdate = await page.evaluate(() => window.pomme.renderer.stats().meshUploadCount);
  joined.write('block_change', { location: { x: -9, y: -20, z: -10 }, type: 0 });
  await page.waitForFunction(() => window.pomme.core.block_get(-9,-20,-10) === 0);
  await page.waitForFunction(before => window.pomme.renderer.stats().meshUploadCount > before, beforeUpdate);
  joined.write('block_change', { location: { x: -9, y: -20, z: -10 }, type: slab });
